// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Private_Bank c;
    function setUp() public { c = new Private_Bank(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(c) && actor != address(this) && actor != address(0));
        amount = bound(amount, 2 ether, 100 ether);

        vm.deal(actor, amount + amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 before = c.balances(actor);
        vm.prank(actor);
        c.CashOut(amount);
        uint256 afterB = c.balances(actor);

        assertTrue(before - amount == afterB);
    }
}
